import type { SeekerNeeds } from "@/lib/matching/needs"
import raw from "./embeddings-data.json"

// Loaded from lib/eval/embeddings-data.json, generated by
// `npm run embeddings:eval`. Server-only: the file is a few MB and includes
// 1536-number vectors, no reason to ship it to the browser.
export type EvalData = {
  model: string
  generatedAt: string
  shelters: {
    id: string
    name: string
    description: string
    embedding: number[]
  }[]
  needs: {
    caseNumber: number
    needs: SeekerNeeds
    text: string
    embedding: number[]
  }[]
}

export function loadEvalData(): EvalData | null {
  const data = raw as EvalData

  if (!data.shelters?.length || !data.needs?.length) {
    return null
  }

  return data
}
